#!/usr/bin/env bash
# read-out mail for a candidate arm TAG (2026-09-30): event check, families, held-out pass rates from the training summaries
TAG=${1:-_gneg}; A=${MADGRAV_SCRATCH}/madgrav2/arm; OUT=$A/models/READOUT_ARM${TAG}.txt
{ echo "MADGRAV 2.1 candidate arm $TAG -- read-out $(date '+%F %H:%M')"; echo; echo "== event check (233 catalogue windows; compare _def 93/116, _off5 109/116, det70 must hold)"; head -14 $A/models/event_check${TAG}.txt; grep -E "^RECOVERED|^LOST|^det72" $A/models/event_check${TAG}.txt | cut -c1-1500; echo; echo "== FAR families (off5: 511/532; fail below 500)"; grep -E "families|adopted|missed" $A/score_${TAG#_}_*.log 2>/dev/null | tail -4; cat $A/models/score_families${TAG}.json 2>/dev/null; echo; echo "== held-out pass rates at 1% signal loss, best epoch per model (off5 reference: see arm_off5_*.json)"; for j in $A/models/arm${TAG}_f*_s*.json; do echo "$(basename $j): $(${PY:-python} -c "import json,sys; d=json.load(open('$j')); print({k:(round(v,4) if isinstance(v,float) else v) for k,v in d.items() if any(x in k for x in ('pass','auc','epoch','loss'))})" 2>/dev/null)"; done; } > $OUT 2>&1
${PY:-python} ${MADGRAV_SCRATCH}/MADGRAV1/search_mode/pastro_final/campaign/mailer.py "[MADGRAV] candidate arm $TAG read-out" $OUT; cat $OUT
